$major = false;
if (preg_match('/^(\d+\.\d+)/', (string)($r['live_version'] ?? ''), $m1) && preg_match('/^(\d+\.\d+)/', (string)($r['latest_version'] ?? ''), $m2)) $major = $m1[1] !== $m2[1];
?><?php if(!empty($r['update_available'])):?><form method="post" action="/fleet/update" style="display:inline"<?=($major ? " onsubmit=\"return confirm('This crosses a minor boundary (".Helpers::e($r['live_version'])." → ".Helpers::e($r['latest_version'])."). A restore point is taken first — proceed?')\"" : '')?>><input type="hidden" name="csrf" value="<?=Helpers::csrf()?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="mode" value="core"><?php if($major):?><input type="hidden" name="allow_major" value="1"><?php endif;?><button class="btn small" title="Update WordPress core (snapshot first, rollback on failure)">⬆ Core</button></form><?php endif;?>
<?php if(!empty($r['plugins_available'])):?><form method="post" action="/fleet/update" style="display:inline"><input type="hidden" name="csrf" value="<?=Helpers::csrf()?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="mode" value="plugins"><button class="btn small" title="<?= (int)$r['plugins_available'] ?> plugin(s) updatable (snapshot first, rollback on failure)">🧩 Plugins (<?=(int)$r['plugins_available']?>)</button></form><?php endif;?><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></table>
